def inline(text: str) -> str:
    codes=[]
    def code(m):
        codes.append('<code>'+html.escape(m[1])+'</code>')
        return '\x00'+str(len(codes)-1)+'\x00'
    text=html.escape(re.sub(r'`([^`]+)`',code,text))
    text=re.sub(r'\[([^\]]+)\]\(([^\s)]+)\)',lambda m:'<a href="'+m[2]+'">'+m[1]+'</a>',text)
    text=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',text)
    def citation(m):
        body=m[1]
        range_match=re.fullmatch(r'([EWU])(\d{2})[–-](?:[EWU])?(\d{2})',body)
        ids=[range_match[1]+f'{i:02}' for i in range(int(range_match[2]),int(range_match[3])+1)] if range_match else [body]
        return ''.join('<a class="cite" href="#ref-'+x+'">['+x+']</a>' for x in ids)
    text=re.sub(r'\[([EWU]\d{2}(?:[–-](?:[EWU])?\d{2})?)\]',citation,text)
    for i,c in enumerate(codes):text=text.replace('\x00'+str(i)+'\x00',c)
    return text


def markdown(text: str) -> str:
    lines=text.splitlines();out=[];i=0;list_type=None
    def close_list():
        nonlocal list_type
        if list_type:out.append('</'+list_type+'>');list_type=None
    while i<len(lines):
        line=lines[i]
        if line.startswith('```'):
            close_list();body=[];i+=1
            while i<len(lines) and not lines[i].startswith('```'):body.append(lines[i]);i+=1
            out.append('<pre><code>'+html.escape('\n'.join(body))+'</code></pre>');i+=1;continue
        if line.startswith('|') and i+1<len(lines) and re.match(r'^\|[\s:|-]+\|\s*$',lines[i+1]):
            close_list();head=[v.strip() for v in line.strip('|').split('|')];i+=2;rows=[]
            while i<len(lines) and lines[i].startswith('|'):rows.append([v.strip() for v in lines[i].strip('|').split('|')]);i+=1
            out.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>');continue
        li=re.match(r'^\s*(- |\d+\. )(.+)$',line)
        if li:
            kind='ul' if li[1]=='- ' else 'ol'
            if list_type!=kind:close_list();out.append('<'+kind+'>');list_type=kind
            out.append('<li>'+inline(li[2])+'</li>');i+=1;continue
        close_list()
        heading=re.match(r'^(#{1,6}) (.+)$',line)
        if heading:
            level=min(6,len(heading[1])+1);out.append(f'<h{level}>'+inline(heading[2])+f'</h{level}>')
        elif line.strip():out.append('<p>'+inline(line)+'</p>')
        i+=1
    close_list();return '\n'.join(out)


